const camera=new THREE.PerspectiveCamera(76,innerWidth/innerHeight,.08,120);camera.position.set(0,1.7,13);scene.add(camera);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;host.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xcfe8ff,0x35312d,2.2));const sun=new THREE.DirectionalLight(0xffe6c6,3.2);sun.position.set(-12,23,9);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-30;sun.shadow.camera.right=30;sun.shadow.camera.top=30;sun.shadow.camera.bottom=-30;scene.add(sun);
const mat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const mats={ground:mat(0x69716a),concrete:mat(0xaaa79a),light:mat(0xc9c5b7),dark:mat(0x343b40),red:mat(0xe74450),teal:mat(0x36b8b1),wood:mat(0x795b43),metal:mat(0x4c565d,.45,.6),glass:new THREE.MeshStandardMaterial({color:0x77c8cb,roughness:.2,metalness:.45,emissive:0x0b3436})};
const colliders=[];const boxGeo=new THREE.BoxGeometry(1,1,1);
function box(x,y,z,w,h,d,material,collide=true){const m=new THREE.Mesh(boxGeo,material);m.position.set(x,y,z);m.scale.set(w,h,d);m.castShadow=h>1;m.receiveShadow=true;scene.add(m);if(collide)colliders.push({x,z,w,d});return m}
function cylinder(x,y,z,r,h,material,sides=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,sides),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
