box(-13,3,-12,13,6,9,mats.light);box(-13,6.1,-12,13,.25,9,mats.red,false);box(-13,1.8,-7.42,5,3.5,.12,mats.dark,false);box(-16.5,4,-7.36,1.1,2.4,.15,mats.glass,false);box(-9.5,4,-7.36,1.1,2.4,.15,mats.glass,false);
