box(-5,1.15,-7,4.2,2.3,2.5,mats.wood);box(-5,2.34,-7,4.3,.16,2.6,mats.metal,false);box(4,1.05,-10,3.1,2.1,2.5,mats.dark);box(4,2.15,-10,3.15,.12,2.56,mats.red,false);
