const siteRing=new THREE.Mesh(new THREE.TorusGeometry(4.2,.055,8,64),new THREE.MeshBasicMaterial({color:0xff4655,transparent:true,opacity:.65}));siteRing.rotation.x=Math.PI/2;siteRing.position.set(0,.06,-2);scene.add(siteRing);
for(let i=0;i<16;i++){const x=Math.sin(i*8.2)*24,z=Math.cos(i*6.4)*20;if(Math.abs(x)<4&&z<5&&z>-8)continue;const trunk=cylinder(x,.55,z,.12,1.1,mat(0x554c3e));const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.75,1),mat(0x566d61));crown.position.set(x,1.35,z);crown.castShadow=true;scene.add(crown)}
