const gunMat=mat(0x202832,.38,.55),gunAccent=mat(0xd84450,.42,.35);function gunBox(x,y,z,w,h,d,m){const o=new THREE.Mesh(boxGeo,m);o.position.set(x,y,z);o.scale.set(w,h,d);gun.add(o);return o}
gunBox(0,0,0,.15,.16,.58,gunMat);gunBox(0,.055,-.2,.19,.09,.22,gunAccent);gunBox(0,.025,-.46,.055,.05,.44,gunMat);gunBox(0,-.105,.08,.105,.2,.17,gunMat);gunBox(0,.102,.02,.055,.035,.16,mat(0x11161a));const muzzle=new THREE.PointLight(0xffb66b,0,4);muzzle.position.set(0,.03,-.7);gun.add(muzzle);
// Player / state
const player={pos:new THREE.Vector3(0,1.7,13),vel:new THREE.Vector3(),yaw:0,pitch:0,hp:100,ammo:24,reserve:120,round:1,alive:true};camera.position.copy(player.pos);
let enemies=[],running=false,paused=false,roundOver=false,planting=false,planted=false,plantTime=0,spikeTime=0,fireTimer=0,reloadTimer=0,blinkCooldown=0,reconCooldown=0,walkTime=0,shootFlash=0,mouseDown=false,muted=false;
const keys={};const raycaster=new THREE.Raycaster();const center=new THREE.Vector2(0,0);const clock=new THREE.Clock();
const $=s=>document.querySelector(s);
function makeEnemy(index){const root=new THREE.Group();const armor=mat([0x4b2830,0x45323e,0x372d38,0x4a3034,0x333d46][index%5]);const trim=mat(0xff4655,.4,.25),dark=mat(0x252a32);const body=new THREE.Mesh(new THREE.CapsuleGeometry(.37,.68,4,8),armor);body.position.y=1.08;body.castShadow=true;root.add(body);const chest=new THREE.Mesh(new THREE.BoxGeometry(.61,.5,.23),dark);chest.position.set(0,1.25,-.15);chest.castShadow=true;root.add(chest);const head=new THREE.Mesh(new THREE.SphereGeometry(.26,12,10),mat(0xb78c76));head.position.y=1.83;head.castShadow=true;root.add(head);const visor=new THREE.Mesh(new THREE.BoxGeometry(.38,.09,.1),trim);visor.position.set(0,1.87,-.22);root.add(visor);const legs=[];for(const x of [-.19,.19]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.11,.55,3,6),dark);leg.position.set(x,.43,0);leg.castShadow=true;root.add(leg);legs.push(leg)}const gunmesh=new THREE.Mesh(new THREE.BoxGeometry(.12,.12,.58),gunMat);gunmesh.position.set(.37,1.14,-.27);root.add(gunmesh);scene.add(root);const starts=[[-10,1],[-1,-13],[11,-4],[17,8],[-17,-6],[5,18],[21,-16],[-20,4]];let [x,z]=starts[index%starts.length];root.position.set(x,0,z);return{root,hp:100,alive:true,shot:1+Math.random(),speed:1.05+Math.random()*.38,legs,index}}
function spawnEnemies(){enemies.forEach(e=>scene.remove(e.root));enemies=Array.from({length:Math.min(4+player.round,8)},(_,i)=>makeEnemy(i));updateHUD();}
function updateHUD(){$('#healthNum').textContent=Math.max(0,Math.ceil(player.hp));$('#healthFill').style.width=Math.max(0,player.hp)+'%';$('#ammoNow').textContent=player.ammo;$('#ammoReserve').textContent=player.reserve;$('#round').textContent=String(player.round).padStart(2,'0');$('#objectiveText').textContent=planted?`DEFEND SPIKE: ${Math.max(0,Math.ceil(12-spikeTime))} SEC`:`HOSTILES REMAINING: ${enemies.filter(e=>e.alive).length.toString().padStart(2,'0')}`;}
function showMessage(text,duration=1300){const el=$('#centerMessage');el.textContent=text;el.classList.add('show');clearTimeout(showMessage.timer);showMessage.timer=setTimeout(()=>el.classList.remove('show'),duration)}
function killfeed(){const el=document.createElement('div');el.className='kill-item';el.innerHTML='<b>YOU</b> &nbsp;✕&nbsp; HOSTILE';$('#killfeed').prepend(el);setTimeout(()=>el.remove(),4000)}
function startRound(){player.hp=100;player.ammo=24;player.reserve=120;player.alive=true;player.pos.set(0,1.7,13);player.yaw=0;player.pitch=0;camera.position.copy(player.pos);camera.rotation.set(0,0,0);planted=false;planting=false;plantTime=0;spikeTime=0;roundOver=false;spawnEnemies();$('#endScreen').classList.add('hidden');$('#roundBanner').querySelector('span').textContent='ROUND '+String(player.round).padStart(2,'0');$('#roundBanner').querySelector('b').textContent='ATTACKERS';updateHUD();showMessage('ROUND '+String(player.round).padStart(2,'0')+' // FIGHT',1800);}
function endRound(win){if(roundOver)return;roundOver=true;running=false;document.exitPointerLock?.();$('#endKicker').textContent=win?'ROUND COMPLETE':'MISSION FAILED';$('#endTitle').textContent=win?'SITE SECURED':'OPERATIVE DOWN';$('#endCopy').textContent=win?'The defenders have been eliminated. Take the next site.':'The site is lost. Regroup and try again.';$('#nextBtn').querySelector('span').textContent=win?'NEXT ROUND':'RETRY ROUND';$('#endScreen').classList.remove('hidden');}
function removeEnemy(e){if(!e.alive)return;e.alive=false;scene.remove(e.root);killfeed();updateHUD();if(enemies.every(b=>!b.alive))endRound(true)}
function fire(){if(!running||paused||!player.alive||reloadTimer>0||fireTimer>0)return;if(player.ammo<=0){reload();return}player.ammo--;fireTimer=.115;shootFlash=.045;muzzle.intensity=4.5;gun.position.z=-.61;camera.rotation.x-=.004;updateHUD();raycaster.setFromCamera(center,camera);raycaster.far=90;let target=null,targetHit=null,best=Infinity;for(const e of enemies){if(!e.alive)continue;const hits=raycaster.intersectObjects(e.root.children,false);if(hits.length&&hits[0].distance<best){best=hits[0].distance;target=e;targetHit=hits[0]}}if(target){const head=targetHit.object.position.y>1.6;target.hp-=head?100:38;const h=$('#hitmarker');h.classList.remove('active');void h.offsetWidth;h.classList.add('active');if(target.hp<=0)removeEnemy(target);else showMessage(head?'HEADSHOT':'',300)}}
function reload(){if(!running||player.ammo===24||player.reserve<=0||reloadTimer>0)return;reloadTimer=1.45;showMessage('RELOADING',800);setTimeout(()=>{if(reloadTimer>0){const n=Math.min(24-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;reloadTimer=0;updateHUD()}},1450)}
function blink(){if(!running||blinkCooldown>0)return;const direction=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));if(keys.KeyS)direction.negate();if(keys.KeyA)direction.set(-Math.cos(player.yaw),0,Math.sin(player.yaw));if(keys.KeyD)direction.set(Math.cos(player.yaw),0,-Math.sin(player.yaw));player.pos.addScaledVector(direction,4.1);player.pos.x=THREE.MathUtils.clamp(player.pos.x,-25,25);player.pos.z=THREE.MathUtils.clamp(player.pos.z,-22,22);blinkCooldown=5;$('#crosshair').style.filter='drop-shadow(0 0 9px #5ee9e6)';setTimeout(()=>$('#crosshair').style.filter='',350);showMessage('BLINK',500)}
function recon(){if(!running||reconCooldown>0)return;reconCooldown=8;for(const e of enemies)if(e.alive){const d=e.root.position.distanceTo(player.pos);const dot=document.createElement('i');dot.className='radar-dot';const a=Math.atan2(e.root.position.x-player.pos.x,e.root.position.z-player.pos.z)-player.yaw;const r=Math.min(49,d*2.7);dot.style.left=`${70+Math.sin(a)*r}px`;dot.style.top=`${70-Math.cos(a)*r}px`;$('#radar').append(dot);setTimeout(()=>dot.remove(),2200)}showMessage('RECON PULSE',900)}
function plant(){if(!running||planted||planting)return;const d=Math.hypot(player.pos.x,player.pos.z+2);if(d>5){showMessage('MOVE TO THE SITE',900);return}planting=true;plantTime=2.2;showMessage('PLANTING SPIKE...',2400);}
function movement(dt){const f=(keys.KeyW?1:0)-(keys.KeyS?1:0)+(touchMove.y||0),s=(keys.KeyD?1:0)-(keys.KeyA?1:0)+(touchMove.x||0);const mag=Math.hypot(f,s);if(mag>0){const speed=keys.ShiftLeft||keys.ShiftRight?8:5.2;const dx=(-Math.sin(player.yaw)*f+Math.cos(player.yaw)*s)/mag*speed*dt;const dz=(-Math.cos(player.yaw)*f-Math.sin(player.yaw)*s)/mag*speed*dt;const nx=player.pos.x+dx,nz=player.pos.z+dz;let block=colliders.some(c=>Math.abs(nx-c.x)<c.w/2+.38&&Math.abs(player.pos.z-c.z)<c.d/2+.38);if(!block)player.pos.x=THREE.MathUtils.clamp(nx,-25.5,25.5);block=colliders.some(c=>Math.abs(player.pos.x-c.x)<c.w/2+.38&&Math.abs(nz-c.z)<c.d/2+.38);if(!block)player.pos.z=THREE.MathUtils.clamp(nz,-22.5,22.5);walkTime+=dt*speed;camera.position.y=1.7+Math.sin(walkTime*1.6)*Math.min(.035,mag*.014);gun.position.y=-.3+Math.sin(walkTime*3)*.008}else camera.position.y=1.7;camera.position.x=player.pos.x;camera.position.z=player.pos.z;camera.rotation.order='YXZ';camera.rotation.y=player.yaw;camera.rotation.x=player.pitch;}
const touchMove={x:0,y:0};function enemyAI(dt){for(const e of enemies){if(!e.alive)continue;const p=e.root.position;const target=new THREE.Vector3(player.pos.x,0,player.pos.z);const delta=target.sub(p);const dist=delta.length();e.root.rotation.y=Math.atan2(-delta.x,-delta.z);if(dist>7.5){const v=delta.normalize().multiplyScalar(e.speed*dt);const nx=p.x+v.x,nz=p.z+v.z;if(!colliders.some(c=>Math.abs(nx-c.x)<c.w/2+.5&&Math.abs(p.z-c.z)<c.d/2+.5))p.x=nx;if(!colliders.some(c=>Math.abs(p.x-c.x)<c.w/2+.5&&Math.abs(nz-c.z)<c.d/2+.5))p.z=nz;e.legs.forEach((l,i)=>l.rotation.x=Math.sin(performance.now()*.009+i*Math.PI)*.42)}else e.legs.forEach(l=>l.rotation.x=0);e.shot-=dt;if(dist<24&&e.shot<=0){e.shot=1.15+Math.random()*.8;const chance=Math.max(.22,.62-dist*.014);if(Math.random()<chance){player.hp-=Math.random()<.2?16:9;$('#damageFlash').classList.add('active');setTimeout(()=>$('#damageFlash').classList.remove('active'),170);updateHUD();if(player.hp<=0){player.alive=false;endRound(false)}}}}}
function update(dt){fireTimer=Math.max(0,fireTimer-dt);blinkCooldown=Math.max(0,blinkCooldown-dt);reconCooldown=Math.max(0,reconCooldown-dt);shootFlash=Math.max(0,shootFlash-dt);muzzle.intensity=shootFlash>0?4.5:0;gun.position.z=THREE.MathUtils.lerp(gun.position.z,-.67,Math.min(1,dt*14));if(!running||paused||roundOver)return;movement(dt);enemyAI(dt);if(planting){plantTime-=dt;if(plantTime<=0){planting=false;planted=true;spikeTime=0;const orb=new THREE.Mesh(new THREE.OctahedronGeometry(.32,1),new THREE.MeshStandardMaterial({color:0xff4655,emissive:0xff172c,emissiveIntensity:2}));orb.position.set(player.pos.x,.5,player.pos.z);scene.add(orb);showMessage('SPIKE PLANTED // DEFEND',1800)}}if(planted){spikeTime+=dt;if(spikeTime>=12){endRound(true);return}const near=enemies.some(e=>e.alive&&e.root.position.distanceTo(new THREE.Vector3(player.pos.x,0,player.pos.z))<2.1);if(near&&Math.floor(spikeTime)%2===0&&Math.abs((spikeTime%1)-.02)<dt){showMessage('SPIKE UNDER PRESSURE',700)}}updateHUD();}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);update(dt);renderer.render(scene,camera)}animate();
// Controls: pointer lock on desktop; drag-to-look and virtual stick on touch.
const canvas=renderer.domElement;function lock(){if(!matchMedia('(pointer:coarse)').matches)canvas.requestPointerLock?.()}
$('#playBtn').addEventListener('click',()=>{$('#startScreen').classList.add('hidden');running=true;startRound();lock()});$('#resumeBtn').addEventListener('click',()=>{paused=false;running=true;$('#pauseScreen').classList.add('hidden');lock()});$('#nextBtn').addEventListener('click',()=>{if($('#endKicker').textContent==='MISSION FAILED'){}else player.round++;$('#endScreen').classList.add('hidden');running=true;startRound();lock()});
$('#pauseBtn').addEventListener('click',()=>{if(!roundOver){paused=true;running=false;$('#pauseScreen').classList.remove('hidden');document.exitPointerLock?.()}});document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==canvas&&running&&!roundOver&&!matchMedia('(pointer:coarse)').matches){paused=true;running=false;$('#pauseScreen').classList.remove('hidden')}});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas){player.yaw-=e.movementX*.0022;player.pitch=THREE.MathUtils.clamp(player.pitch-e.movementY*.0018,-1.35,1.35)}});canvas.addEventListener('mousedown',e=>{if(e.button===0){if(!running||paused)return;if(document.pointerLockElement!==canvas&&!matchMedia('(pointer:coarse)').matches){lock();return}mouseDown=true;fire()}});document.addEventListener('mouseup',()=>mouseDown=false);
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyR')reload();if(e.code==='KeyQ')blink();if(e.code==='KeyE')recon();if(e.code==='KeyF')plant();if(e.code==='Escape'&&running&&!roundOver){paused=true;running=false;$('#pauseScreen').classList.remove('hidden')}});document.addEventListener('keyup',e=>keys[e.code]=false);$('#soundBtn').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'♪':'♫';showMessage(muted?'AUDIO MUTED':'AUDIO ON',600)});
// Pointer drag fallback on touch screens
let lastTouch=null;canvas.addEventListener('touchstart',e=>{if(e.touches.length===1){lastTouch={x:e.touches[0].clientX,y:e.touches[0].clientY}}},{passive:true});canvas.addEventListener('touchmove',e=>{if(lastTouch&&e.touches.length===1){const t=e.touches[0];player.yaw-=(t.clientX-lastTouch.x)*.006;player.pitch=THREE.MathUtils.clamp(player.pitch-(t.clientY-lastTouch.y)*.005,-1.3,1.3);lastTouch={x:t.clientX,y:t.clientY}}},{passive:true});canvas.addEventListener('touchend',()=>lastTouch=null);
// On-screen joystick + actions
const joy=$('#joystick');let joyRect;joy.addEventListener('touchstart',e=>{joyRect=joy.getBoundingClientRect();joyMove(e)},{passive:false});joy.addEventListener('touchmove',joyMove,{passive:false});joy.addEventListener('touchend',()=>{touchMove.x=touchMove.y=0;joy.querySelector('i').style.transform='translate(0,0)'},{passive:true});function joyMove(e){e.preventDefault();const t=e.touches[0],cx=joyRect.left+joyRect.width/2,cy=joyRect.top+joyRect.height/2;let x=(t.clientX-cx)/42,y=(t.clientY-cy)/42;const l=Math.hypot(x,y);if(l>1){x/=l;y/=l}touchMove.x=x;touchMove.y=-y;joy.querySelector('i').style.transform=`translate(${x*28}px,${y*28}px)`}
$('#mobileFire').addEventListener('touchstart',e=>{e.preventDefault();fire();const rep=setInterval(()=>{if(!mouseDown){clearInterval(rep);return}fire()},120);mouseDown=true;$('#mobileFire').ontouchend=()=>{mouseDown=false;clearInterval(rep)}},{passive:false});$('#mobileReload').addEventListener('click',reload);$('#mobileBlink').addEventListener('click',blink);
